--liquibase formatted sql
--changeset python-agent-platform:19
--comment Wagtail 7.4 columns/tables missing after :16 squash + migrate --fake (CRC site_name). Not in sqlmigrate-map.yaml. Additive only; no ALTER TYPE. Seeds default locale + root collection so collection_id/locale_id defaults are valid.
CREATE TABLE "wagtailsearch_indexentry" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "content_type_id" integer NOT NULL, "object_id" varchar(50) NOT NULL, "title_norm" double precision NOT NULL, "autocomplete" tsvector NOT NULL, "title" tsvector NOT NULL, "body" tsvector NOT NULL, "title_text" text NOT NULL, "body_text" text NOT NULL);
CREATE TABLE "wagtailadmin_admin" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE "wagtailadmin_editingsession" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL, "content_type_id" integer NOT NULL, "object_id" varchar(255) NOT NULL, "last_seen_at" timestamp with time zone NOT NULL, "is_editing" boolean NOT NULL);
CREATE TABLE "wagtailadmin_formstate" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "data" text NOT NULL, "user_id" bigint NOT NULL, "content_type_id" integer NOT NULL, "object_id" varchar(255) NOT NULL, "parent_object_id" varchar(255) NOT NULL, "last_updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "wagtailcore_locale" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "language_code" varchar(100) NOT NULL UNIQUE);
CREATE TABLE "wagtailcore_groupsitepermission" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "group_id" integer NOT NULL, "site_id" integer NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "wagtailcore_modellogentry" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "content_type_id" integer NULL, "label" text NOT NULL, "action" varchar(255) NOT NULL, "data" jsonb NOT NULL, "timestamp" timestamp with time zone NOT NULL, "uuid" uuid NULL, "user_id" bigint NULL, "revision_id" integer NULL, "content_changed" boolean NOT NULL, "deleted" boolean NOT NULL, "object_id" varchar(255) NOT NULL);
CREATE TABLE "wagtailcore_revision" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "content_type_id" integer NOT NULL, "base_content_type_id" integer NOT NULL, "object_id" varchar(255) NOT NULL, "created_at" timestamp with time zone NOT NULL, "user_id" bigint NULL, "object_str" text NOT NULL, "content" jsonb NOT NULL, "approved_go_live_at" timestamp with time zone NULL);
CREATE TABLE "wagtailcore_collectionviewrestriction" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "restriction_type" varchar(20) NOT NULL, "password" varchar(255) NOT NULL, "collection_id" integer NOT NULL);
CREATE TABLE "wagtailcore_collectionviewrestriction_groups" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "collectionviewrestriction_id" integer NOT NULL, "group_id" integer NOT NULL);
CREATE TABLE "wagtailcore_collection" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "path" varchar(255) NOT NULL UNIQUE, "depth" integer NOT NULL CHECK ("depth" >= 0), "numchild" integer NOT NULL CHECK ("numchild" >= 0), "name" varchar(255) NOT NULL);
CREATE TABLE "wagtailcore_groupcollectionpermission" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "group_id" integer NOT NULL, "collection_id" integer NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "wagtailcore_uploadedfile" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "for_content_type_id" integer NULL, "file" varchar(200) NOT NULL, "uploaded_by_user_id" bigint NULL);
CREATE TABLE "wagtailcore_workflowcontenttype" ("content_type_id" integer NOT NULL PRIMARY KEY, "workflow_id" integer NOT NULL);
CREATE TABLE "wagtailcore_workflowstate" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "content_type_id" integer NOT NULL, "base_content_type_id" integer NOT NULL, "object_id" varchar(255) NOT NULL, "workflow_id" integer NOT NULL, "status" varchar(50) NOT NULL, "created_at" timestamp with time zone NOT NULL, "requested_by_id" bigint NULL, "current_task_state_id" integer NULL UNIQUE);
CREATE TABLE "wagtailcore_workflow" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(255) NOT NULL, "active" boolean NOT NULL);
CREATE TABLE "wagtailcore_workflowtask" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "sort_order" integer NULL, "workflow_id" integer NOT NULL, "task_id" integer NOT NULL);
CREATE TABLE "wagtailcore_task" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(255) NOT NULL, "content_type_id" integer NOT NULL, "active" boolean NOT NULL);
CREATE TABLE "wagtailcore_groupapprovaltask" ("task_ptr_id" integer NOT NULL PRIMARY KEY);
CREATE TABLE "wagtailcore_groupapprovaltask_groups" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "groupapprovaltask_id" integer NOT NULL, "group_id" integer NOT NULL);
CREATE TABLE "wagtailcore_taskstate" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "workflow_state_id" integer NOT NULL, "revision_id" integer NOT NULL, "task_id" integer NOT NULL, "status" varchar(50) NOT NULL, "started_at" timestamp with time zone NOT NULL, "finished_at" timestamp with time zone NULL, "finished_by_id" bigint NULL, "comment" text NOT NULL, "content_type_id" integer NOT NULL);
CREATE TABLE "wagtailcore_workflowpage" ("page_id" integer NOT NULL PRIMARY KEY, "workflow_id" integer NOT NULL);
CREATE TABLE "wagtailcore_pagelogentry" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "content_type_id" integer NULL, "label" text NOT NULL, "action" varchar(255) NOT NULL, "data" jsonb NOT NULL, "timestamp" timestamp with time zone NOT NULL, "uuid" uuid NULL, "user_id" bigint NULL, "revision_id" integer NULL, "content_changed" boolean NOT NULL, "deleted" boolean NOT NULL, "page_id" integer NOT NULL);
CREATE TABLE "wagtailcore_comment" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "page_id" integer NOT NULL, "user_id" bigint NOT NULL, "text" text NOT NULL, "contentpath" text NOT NULL, "position" text NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL, "revision_created_id" integer NULL, "resolved_at" timestamp with time zone NULL, "resolved_by_id" bigint NULL);
CREATE TABLE "wagtailcore_commentreply" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "comment_id" integer NOT NULL, "user_id" bigint NOT NULL, "text" text NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "wagtailcore_pagesubscription" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL, "page_id" integer NOT NULL, "comment_notifications" boolean NOT NULL);
CREATE TABLE "wagtailcore_referenceindex" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "content_type_id" integer NOT NULL, "base_content_type_id" integer NOT NULL, "object_id" varchar(255) NOT NULL, "to_content_type_id" integer NOT NULL, "to_object_id" varchar(255) NOT NULL, "model_path" text NOT NULL, "content_path" text NOT NULL, "content_path_hash" uuid NOT NULL);

INSERT INTO "wagtailcore_locale" ("language_code")
SELECT 'en'
WHERE NOT EXISTS (SELECT 1 FROM "wagtailcore_locale" WHERE "language_code" = 'en');
INSERT INTO "wagtailcore_collection" ("path", "depth", "numchild", "name")
SELECT '0001', 1, 0, 'Root'
WHERE NOT EXISTS (SELECT 1 FROM "wagtailcore_collection" WHERE "path" = '0001');
